package com.englishhero.practice;

import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.ObjectMapper;
import com.englishhero.identity.SessionPrincipal;
import com.englishhero.reading.*;
import com.englishhero.web.BusinessException;
import static com.englishhero.practice.PracticeDtos.*;
import static com.englishhero.practice.PracticeSubjectiveDtos.*;

/** Subjective content shares set/version lifecycle, never creates synthetic quizzes. */
@Service
@Transactional(isolation=Isolation.READ_COMMITTED)
public class PracticeSubjectiveAdminService {
 private final org.springframework.jdbc.core.JdbcTemplate jdbc;private final PracticeSetMapper sets;private final ArticleMapper articles;private final AdminArticleService admin;private final PracticePublicationChecks checks;private final ObjectMapper json;
 public PracticeSubjectiveAdminService(PracticeSetMapper sets,ArticleMapper articles,AdminArticleService admin,PracticePublicationChecks checks,ObjectMapper json,org.springframework.jdbc.core.JdbcTemplate jdbc){this.jdbc=jdbc;this.sets=sets;this.articles=articles;this.admin=admin;this.checks=checks;this.json=json;}
 public Content content(long id,boolean published){return json.readValue(sets.subjective(id,published),Content.class);}
 private DraftState state(PracticeSetMapper.Row r){return json.readValue(r.metadata(),DraftState.class);}
 private Metadata metadata(AdminInput d){if(d==null)throw BusinessException.invalid("metadata","请填写题目信息");return PracticeDraftRules.normalizeMetadata(d.metadata());}
 private PracticeSetMapper.Row locked(String id,Integer expected){var row=sets.get(ArticleRules.id(id,"setId"),true);if(row==null||!PracticeSubjectiveRules.isSubjective(row.readingType()))throw PracticeAdminService.missing();PracticeAdminService.lock(expected,row.lockVersion());return row;}
 private String contentHash(PracticeSetMapper.Row r){return checks.hash(List.of(r.articleVersionId(),content(r.id(),false)));}
 private String sourceHash(PracticeSetMapper.Row r){return checks.hash(List.of(contentHash(r),state(r).metadata()));}
 public AdminSet create(SessionPrincipal actor,AdminInput input){admin.requireAdmin(actor);var m=metadata(input);var c=PracticeSubjectiveRules.normalize(input.readingType(),input.subjective());var category=articles.categories().getFirst();long aid=articles.insertPracticeMaterial(Long.parseLong(category.id()),actor.userId());long vid=material(actor,aid,1,category.id(),m,c);articles.initialDraft(aid,vid);
  long id=sets.insert("INSERT INTO practice_set(article_id,exam_code,reading_type,section,draft_article_version_id,draft_quiz_id,draft_metadata_json,subjective_json,created_by,updated_by) VALUES(?,'CET4',?,?,?,NULL,?,?,?,?)",aid,input.readingType(),input.readingType(),vid,json.writeValueAsString(new DraftState(m,Map.of(),null,input.readingType(),List.of())),json.writeValueAsString(c),actor.userId(),actor.userId());return dto(sets.get(id,false));}
 public AdminSet save(SessionPrincipal actor,String id,AdminInput input){admin.requireAdmin(actor);var m=metadata(input);var c=PracticeSubjectiveRules.normalize(input.readingType(),input.subjective());var r=locked(id,input.expectedLockVersion());if(!r.readingType().equals(input.readingType()))throw BusinessException.invalid("readingType","创建后题型不可改变");var old=content(r.id(),false);var oldState=state(r);long vid=r.articleVersionId();if(!old.prompt().equals(c.prompt())||!oldState.metadata().equals(m)){var a=articles.article(r.articleId(),true);var previous=articles.version(a.id(),a.draftVersionId());vid=material(actor,a.id(),previous.versionNo()+1,""+previous.categoryId(),m,c);if(articles.saveDraft(a.id(),vid,a.lockVersion(),actor.userId())!=1)throw BusinessException.conflict();}
  boolean sameContent=vid==r.articleVersionId()&&old.equals(c);var reviews=sameContent?oldState.reviews():Map.<String,String>of();String source=sameContent&&oldState.metadata().equals(m)?oldState.sourceReview():null;
  jdbc.update("UPDATE practice_set SET draft_article_version_id=?,draft_metadata_json=?,subjective_json=?,lock_version=lock_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",vid,json.writeValueAsString(new DraftState(m,reviews,source,r.readingType(),List.of())),json.writeValueAsString(c),actor.userId(),r.id());return dto(sets.get(r.id(),false));}
 private long material(SessionPrincipal actor,long aid,int revision,String category,Metadata m,Content c){String body=c.prompt().isBlank()?"待补题目材料":c.prompt();var doc=ArticleContent.normalize(body);String title=m.title().isBlank()?"未命名专项题目":m.title().substring(0,Math.min(160,m.title().length()));var input=new ReadingDtos.DraftInput(category,title,m.titleZh().substring(0,Math.min(160,m.titleZh().length())),"写作或翻译题目材料","B2",body,"专项材料",m.sourceKind().equals("PAST")?"THIRD_PARTY":"ORIGINAL",m.sourceUrl(),"仅用于专项练习");return articles.insertVersion(aid,revision,actor.userId(),input,json.writeValueAsString(doc),checks.hash(doc),ArticleContent.wordCount(doc));}
 public List<Check> allChecks(PracticeSetMapper.Row r){var s=state(r);var issues=new ArrayList<>(checks.metadata(s.metadata()));issues.addAll(PracticeSubjectiveRules.contentChecks(content(r.id(),false)));if(!Objects.equals(s.reviews().get("CONTENT"),contentHash(r)))issues.add(new Check("contentReview",null,"尚未校对题目、参考和对照要点"));if(!Objects.equals(s.sourceReview(),sourceHash(r)))issues.add(new Check("sourceReview",null,"尚未确认来源与使用范围"));return issues;}
 private void valid(List<Check> issues){if(!issues.isEmpty()){var f=new LinkedHashMap<String,String>();issues.forEach(i->f.putIfAbsent(i.path(),i.message()));throw new BusinessException(400,"PRACTICE_REVIEW_REQUIRED","请先完成内容与来源校对",f);}}
 public AdminSet review(SessionPrincipal actor,String id,ReviewInput input){admin.requireAdmin(actor);if(input==null||input.reviewed()==null)throw BusinessException.invalid("reviewed","请选择校对状态");var r=locked(id,input.expectedLockVersion());var s=state(r);var reviews=new LinkedHashMap<>(s.reviews());String source=s.sourceReview();if("CONTENT".equals(input.kind())){if(input.reviewed()){valid(PracticeSubjectiveRules.contentChecks(content(r.id(),false)));reviews.put("CONTENT",contentHash(r));}else reviews.remove("CONTENT");source=null;}else if("SOURCE".equals(input.kind())){if(input.reviewed()){valid(checks.metadata(s.metadata()));source=sourceHash(r);}else source=null;}else throw BusinessException.invalid("kind","写作翻译需分别确认CONTENT与SOURCE校对");jdbc.update("UPDATE practice_set SET draft_metadata_json=?,lock_version=lock_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",json.writeValueAsString(new DraftState(s.metadata(),reviews,source,r.readingType(),List.of())),actor.userId(),r.id());return dto(sets.get(r.id(),false));}
 public AdminSet publish(SessionPrincipal actor,String id,Integer expected){admin.requireAdmin(actor);var r=locked(id,expected);valid(allChecks(r));long vid=sets.insert("INSERT INTO practice_set_version(set_id,version_no,article_id,article_version_id,quiz_id,quiz_version_id,reading_type,metadata_json,subjective_json,created_by) VALUES(?,?,?,?,NULL,NULL,?,?,?,?)",r.id(),r.revision()+1,r.articleId(),r.articleVersionId(),r.readingType(),json.writeValueAsString(state(r).metadata()),sets.subjective(r.id(),false),actor.userId());jdbc.update("UPDATE practice_set SET published_version_id=?,status='PUBLISHED',revision=revision+1,lock_version=lock_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",vid,actor.userId(),r.id());return dto(sets.get(r.id(),false));}
 public AdminSet unpublish(SessionPrincipal actor,String id,Integer expected){admin.requireAdmin(actor);var r=locked(id,expected);if(r.publishedVersionId()==null)throw PracticeAdminService.missing();sets.unpublish(r,actor.userId());return dto(sets.get(r.id(),false));}
 public AdminSet dto(PracticeSetMapper.Row r){var s=state(r);return new AdminSet(""+r.id(),""+r.articleId(),""+r.articleVersionId(),r.exam(),r.readingType(),s.metadata(),List.of(),List.of(),Objects.equals(s.sourceReview(),sourceHash(r)),r.status(),r.revision(),r.lockVersion(),admin.version(r.articleId(),r.articleVersionId()),allChecks(r),true,List.of(),null,content(r.id(),false));}
 public PublishedVersion publishedDto(PracticeSetMapper.Version v){return new PublishedVersion(v.revision(),v.publishedAt(),json.readValue(v.metadata(),Metadata.class),admin.version(v.articleId(),v.articleVersionId()),List.of(),v.readingType(),List.of(),null,content(v.id(),true));}
}
